process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const AKC='', TEI='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'teis1', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'teis1');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'TEIS1'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  for(const [opt,val] of [['ps_uxd_akc',AKC],['ps_uxd_tei',TEI]]){
    const s=await snip('TEMP teis1 '+opt, "update_option('"+opt+"','"+val+"','no');");
    await pause(1800); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  }
  const sd=await snip('TEMP teis1 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd10=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw='nejson'; }
  await pause(2000);
  resp=await fetch(`${WP}/?ps_darb=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.role=JSON.parse(await resp.text()); }catch(e){ out.role_raw=(await resp.text()).slice(0,300); }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.setDefaultTimeout(12000);

  /* PRISIJUNGIAM KAIP DARBUOTOJAS */
  await page.goto(`${WP}/?ps_darblog=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});
  await pause(2000);
  out.darbuotojo_url=page.url();
  out.mato_kataloga=await page.evaluate(()=>!!document.querySelector('.pskat-t, .pskat-bar'));
  out.wp_meniu=await page.evaluate(()=>Array.prototype.map.call(
    document.querySelectorAll('#adminmenu > li > a'), a=>a.textContent.replace(/\d+/g,'').trim()).filter(Boolean));
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/teis1_katalogas.png', png.toString('base64'),'teis1');

  /* AR PATENKA I AKCIJAS */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-akcijos`,{waitUntil:'networkidle',timeout:60000});
  await pause(1500);
  out.mato_akcijas=await page.evaluate(()=>!!document.querySelector('.psakc-app'));

  /* AR BLOKUOJAMI DRAUDZIAMI PUSLAPIAI */
  out.blokuota={};
  for(const u of ['admin.php?page=wc-settings','plugins.php','users.php','options-general.php','admin.php?page=snippets']){
    await page.goto(`${WP}/wp-admin/${u}`,{waitUntil:'domcontentloaded',timeout:45000});
    await pause(600);
    out.blokuota[u]=await page.evaluate(()=>{
      const t=document.body.innerText||'';
      if(t.indexOf('Šis skyrius neprieinamas')>=0) return 'blokuota (musu langas)';
      if(t.indexOf('neturite teisi')>=0 || t.indexOf('Sorry, you are not allowed')>=0
         || t.indexOf('nepakanka teisi')>=0) return 'blokuota (WP)';
      return 'ATIDARE: '+t.slice(0,60).replace(/\n/g,' ');
    });
  }
  png=await page.screenshot(); out.s2=await putRaw('screenshots/teis1_blokuota.png', png.toString('base64'),'teis1');

  /* AR GALI TRINTI PREKE */
  await page.goto(`${WP}/wp-admin/edit.php?post_type=product`,{waitUntil:'networkidle',timeout:60000});
  await pause(1500);
  out.prekiu_sarase=await page.evaluate(()=>{
    const eil=document.querySelector('#the-list tr');
    return eil?{turi_trash:!!eil.querySelector('.trash a'), veiksmai:(eil.querySelector('.row-actions')||{}).innerText}:null;
  });

  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/teis1.json', out);
}
main().catch(async e=>{ await putJson('analize/teis1.json',{klaida:String(e).slice(0,400)}); });
